const APP_BASE_URL = 'https://app.example.com';   // TODO: your deep-link base
const MIN_CONF = 0.6;                              // below this -> human handoff
const ACTIONS = ['send_tender_digest', 'send_nudge', 'send_onboarding_help', 'request_referral', 'human_handoff', 'no_action', 'none'];
const CHANNELS = ['email', 'in_app', 'human', 'none'];

function tenderBlock(c) {
  const tenders = c.top_tenders || [];
  if (!tenders.length) return '';
  const de = c.language !== 'en', loc = de ? 'de-DE' : 'en-GB';
  const L = de ? { dl: 'Frist', val: 'Volumen' } : { dl: 'Deadline', val: 'Value' };
  const eur = v => new Intl.NumberFormat(loc, { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(Number(v));
  const day = d => new Date(d).toLocaleDateString(loc, { day: '2-digit', month: 'short', year: 'numeric' });
  return tenders.map((t, i) => `${i + 1}. ${t.title}\n   ${L.dl}: ${day(t.deadline)} | ${L.val}: ${eur(t.value_eur)}\n   ${APP_BASE_URL}/tenders/${t.tender_id}?utm_source=nba&utm_medium=email`).join('\n\n');
}

function build(c, d) {
  d = { ...d };
  if (!ACTIONS.includes(d.action)) {
    d = { action: 'human_handoff', channel: 'human', timing: 'now', message_angle: 'invalid_output', confidence: 0,
          reasoning: 'Invalid action from model: ' + String(d.action).slice(0, 80) };
  }
  d.confidence = Math.max(0, Math.min(1, Number(d.confidence) || 0));
  if (!CHANNELS.includes(d.channel)) d.channel = 'none';
  const needsHuman = d.action === 'human_handoff' || d.channel === 'human' || d.confidence < MIN_CONF || c.is_high_value === true;
  let routed_to = 'none';
  if (c.arm === 'holdout') routed_to = 'holdout';
  else if (d.action === 'no_action' || d.action === 'none') routed_to = 'none';
  else if (needsHuman) routed_to = 'human';
  else if (d.channel === 'email' || d.channel === 'in_app') routed_to = d.channel;
  const emailText = (d.subject && d.intro) ? (d.intro + '\n\n' + tenderBlock(c)).trim() : null;
  return { json: {
    user_id: c.user_id, arm: c.arm, ab_variant: c.ab_variant, signal_type: c.signal_type,
    action: d.action, channel: d.channel, timing: d.timing || 'now', message_angle: d.message_angle || null,
    confidence: d.confidence, reasoning: d.reasoning || null, routed_to,
    sent: false,   // DRY RUN: nothing is sent. Add a send node after 'Log decision' when you are ready.
    payload: { dry_run: true, subject: d.subject || null, email_text: emailText,
               tender_ids: (c.top_tenders || []).map(t => t.tender_id), signal_detail: c.signal_detail }
  }};
}

const c = $('Get candidates').item.json;
const o = $json.output;
if (!o || $json.error) {
  return build(c, { action: 'human_handoff', channel: 'human', timing: 'now', message_angle: 'agent_failure', confidence: 0,
                    reasoning: 'LLM returned no valid output: ' + JSON.stringify($json.error || '').slice(0, 200) });
}
return build(c, o);

