const c = $json;
if (c.arm === 'holdout') {
  return build(c, { action: 'none', channel: 'none', timing: 'now', message_angle: null, confidence: 1, reasoning: 'Holdout: no touch' });
}
const de = c.language !== 'en';
const R = {
  viewed_no_bid:    { action: 'send_tender_digest', angle: 'deadline_reminder',
    subject: de ? 'Diese Ausschreibungen passen zu Ihrem Gewerk' : 'Open tenders that match your trade',
    intro: de ? 'Sie haben sich kürzlich eine Ausschreibung angesehen. Diese offenen Ausschreibungen passen zu Ihrem Gewerk:' : 'You recently looked at a tender. These open tenders match your trade:' },
  idle_14d:         { action: 'send_tender_digest', angle: 'new_matching_tenders',
    subject: de ? 'Neue passende Ausschreibungen' : 'New tenders that match your trade',
    intro: de ? 'Seit Ihrem letzten Besuch gibt es neue passende Ausschreibungen:' : 'There are new tenders that match your trade since your last visit:' },
  gc_single_tender: { action: 'send_nudge', angle: 'second_tender_prompt',
    subject: de ? 'Ihre nächste Ausschreibung in wenigen Minuten' : 'Post your next tender in minutes',
    intro: de ? 'Sie haben eine Ausschreibung veröffentlicht. Hier erfahren Sie, wie Sie die nächste schnell anlegen.' : 'You posted one tender. Here is how to set up your next one quickly.' },
};
const r = R[c.signal_type];
if (!r) return build(c, { action: 'no_action', channel: 'none', timing: 'now', confidence: 1, reasoning: 'No rule for ' + c.signal_type });
return build(c, { action: r.action, channel: 'email', timing: 'next_business_morning', message_angle: r.angle,
                  confidence: 1, reasoning: 'Static rule for ' + c.signal_type, subject: r.subject, intro: r.intro });

const rows = $input.all().map(i => i.json);
const n = f => rows.filter(f).length;
const tally = k => rows.reduce((a, r) => { a[r[k]] = (a[r[k]] || 0) + 1; return a; }, {});
const agent = rows.filter(r => r.arm === 'agent');
const avgConf = agent.length ? Number((agent.reduce((s, r) => s + Number(r.confidence || 0), 0) / agent.length).toFixed(2)) : null;
const firstEmail = rows.find(r => r.routed_to === 'email' && r.email_preview);
return [{ json: {
  summary: `${rows.length} users processed: ${n(r => r.arm === 'agent')} agent, ${n(r => r.arm === 'rules')} rules baseline, ${n(r => r.arm === 'holdout')} holdout. `
         + `${n(r => r.routed_to === 'email')} email drafts, ${n(r => r.routed_to === 'human')} human handoffs, `
         + `${n(r => r.routed_to === 'holdout' || r.routed_to === 'none')} deliberately not touched. Nothing was sent (dry run).`,
  users_by_arm: tally('arm'),
  decisions_by_route: tally('routed_to'),
  avg_agent_confidence: avgConf,
  human_handoffs: rows.filter(r => r.routed_to === 'human').map(r => ({ company: r.company_name, signal: r.signal_type, arm: r.arm, confidence: Number(r.confidence), why: r.reasoning })),
  example_email: firstEmail ? { to: firstEmail.company_name, arm: firstEmail.arm, subject: firstEmail.email_subject, body: firstEmail.email_preview } : null
}}];

const APP_BASE_URL = 'https://app.example.com';   // TODO: your product deep-link base
const rows = $input.all().map(i => i.json);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const out = [];

for (const r of rows) {
  const de = r.language !== 'en';
  const loc = de ? 'de-DE' : 'en-GB';
  const T = de
    ? { cta: 'Ausschreibung ansehen', home: 'Zur Plattform', deadline: 'Frist', value: 'Volumen',
        left: d => d === 1 ? 'noch 1 Tag' : `noch ${d} Tage`, fallback: 'Neues von Ihrer Plattform',
        footer: 'Vorschau aus einem Testlauf mit synthetischen Daten. Den Abmeldelink ergänzt die E-Mail-Plattform.' }
    : { cta: 'View tender', home: 'Open the platform', deadline: 'Deadline', value: 'Value',
        left: d => d === 1 ? '1 day left' : `${d} days left`, fallback: 'News from your platform',
        footer: 'Preview from a dry run on synthetic data. The unsubscribe link is added by the email platform.' };
  const eur = v => new Intl.NumberFormat(loc, { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(Number(v));
  const day = d => new Date(d).toLocaleDateString(loc, { day: '2-digit', month: 'short', year: 'numeric' });
  const daysLeft = d => Math.max(0, Math.ceil((new Date(d).getTime() - Date.now()) / 864e5));
  const link = tid => `${APP_BASE_URL}${tid ? '/tenders/' + tid : ''}?utm_source=nba&utm_medium=email&utm_campaign=${encodeURIComponent(r.signal_type || 'nba')}&utm_content=${r.decision_id}`;

  const subject = (r.subject || '').trim() || T.fallback;
  const intro = (r.intro || '').trim();
  const tenders = Array.isArray(r.tenders) ? r.tenders : [];

  const cards = tenders.map(t => `
<tr><td style="padding:0 0 14px 0">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e3e6ea;border-radius:8px">
    <tr><td style="padding:16px 18px;font-family:Arial,Helvetica,sans-serif">
      <div style="font-size:16px;font-weight:bold;color:#14213d">${esc(t.title)}</div>
      <div style="font-size:13px;color:#5b6573;margin:4px 0 14px">${esc(t.trade)} · ${esc(t.region)} · ${T.deadline}: ${day(t.deadline)} (${T.left(daysLeft(t.deadline))}) · ${T.value}: ${eur(t.value_eur)}</div>
      <a href="${esc(link(t.tender_id))}" style="display:inline-block;background:#14213d;color:#ffffff;text-decoration:none;font-size:14px;padding:9px 16px;border-radius:6px">${T.cta}</a>
    </td></tr>
  </table>
</td></tr>`).join('');
  const homeButton = tenders.length ? '' : `
<tr><td style="padding:6px 0 14px 0"><a href="${esc(link(null))}" style="display:inline-block;background:#14213d;color:#ffffff;text-decoration:none;font-size:14px;padding:9px 16px;border-radius:6px;font-family:Arial,Helvetica,sans-serif">${T.home}</a></td></tr>`;

  const html = `<!doctype html>
<html lang="${de ? 'de' : 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(subject)}</title></head>
<body style="margin:0;padding:0;background:#f4f5f7">
<div style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(intro)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:10px">
<tr><td style="padding:24px 24px 8px 24px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">
<tr><td style="padding:0 0 16px 0;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;color:#222">${esc(intro)}</td></tr>${cards}${homeButton}
</table></td></tr>
<tr><td style="padding:12px 24px 22px 24px;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#8a919c;border-top:1px solid #eceef1">${T.footer}</td></tr>
</table></td></tr></table></body></html>`;

  const item = { json: {
    to: r.email, company: r.company_name, subject, arm: r.arm, ab_variant: r.ab_variant,
    signal_type: r.signal_type, message_angle: r.message_angle, tenders_included: tenders.length,
    decision_id: r.decision_id, html
  }};
  if (this.helpers && this.helpers.prepareBinaryData) {
    const slug = String(r.company_name || 'email').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
    item.binary = { data: await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), `email_${slug}.html`, 'text/html') };
  }
  out.push(item);
}
return out;
